function openJournal(chunks) {
  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

  let iterator = null;
  let acquired = false;
  let sourceFinished = false;
  let stopped = false;
  let releasePromise = null;

  let chunk = null;
  let offset = 0;
  let fragments = [];
  let line = 1;

  function done() {
    return { done: true, value: undefined };
  }

  function discard() {
    chunk = null;
    offset = 0;
    fragments = [];
  }

  function release() {
    if (releasePromise === null) {
      releasePromise = Promise.resolve().then(async () => {
        if (acquired && iterator != null && !sourceFinished) {
          const returnMethod = iterator.return;
          if (typeof returnMethod === "function") {
            await returnMethod.call(iterator);
          }
        }
      });
    }
    return releasePromise;
  }

  function finishLine(hasDelimiter) {
    const tail = decoder.decode();
    if (tail !== "") fragments.push(tail);

    let text = fragments.join("");
    fragments = [];

    if (hasDelimiter && text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    const currentLine = line++;
    if (text.trim() === "") return null;

    let event;
    try {
      event = {
        line: currentLine,
        ok: true,
        value: JSON.parse(text)
      };
    } catch {
      event = { line: currentLine, ok: false, text };
    }

    return { done: false, value: event };
  }

  async function next() {
    if (stopped) return done();

    try {
      for (;;) {
        if (chunk !== null && offset < chunk.length) {
          const newline = chunk.indexOf(10, offset);
          const end = newline === -1 ? chunk.length : newline;

          const fragment = decoder.decode(chunk.subarray(offset, end), {
            stream: true
          });
          if (fragment !== "") fragments.push(fragment);

          offset = newline === -1 ? end : end + 1;
          if (offset === chunk.length) {
            chunk = null;
            offset = 0;
          }

          if (newline !== -1) {
            const result = finishLine(true);
            if (result !== null) return result;
          }
          continue;
        }

        chunk = null;
        offset = 0;

        if (sourceFinished) {
          const result = finishLine(false);
          stopped = true;
          discard();
          return result === null ? done() : result;
        }

        if (!acquired) {
          iterator = chunks[Symbol.asyncIterator]();
          acquired = true;
        }

        const result = await iterator.next();
        if (stopped) return done();

        if (result.done) {
          sourceFinished = true;
        } else {
          chunk = result.value;
        }
      }
    } catch (error) {
      stopped = true;
      discard();
      try {
        await release();
      } catch {
        // Preserve the original read error.
      }
      throw error;
    }
  }

  async function close() {
    stopped = true;
    discard();
    await release();
  }

  return { next, close };
}
